# idempotent retry with backoff + jitter
import random, time
def call_with_retry(fn, req_id, tries=4):
    delay = 1.0
    for i in range(tries):
        try:
            return fn(req_id)          # server dedups on req_id
        except Timeout:
            time.sleep(delay * (0.5 + random.random()))
            delay *= 2
    raise ServiceDown(req_id)

